import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {
    static int[] solve(int[] nums, int target) {
        // Write your solution here
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        int pos = 0;
        int numsLen = Integer.parseInt(lines.get(pos++).trim());
        int[] nums = new int[numsLen];
        if (numsLen > 0) {
            StringTokenizer st = new StringTokenizer(lines.get(pos));
            for (int i = 0; i < numsLen; i++) nums[i] = Integer.parseInt(st.nextToken());
        }
        pos++;
        int target = Integer.parseInt(lines.get(pos++).trim());
        int[] result = solve(nums, target);
        System.out.println(Arrays.stream(result).mapToObj(String::valueOf).collect(Collectors.joining(" ")));
    }
}

